tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "list_issues",
    "description": "Listet bekannte GitHub-Issues aus dem Snapshot (state=open|closed|all). read-only, schreibt nichts.",
    "parameters": {
      "type": "object",
      "properties": {
        "state": {
          "type": "string",
          "default": "all"
        },
        "limit": {
          "type": "integer",
          "default": 100
        }
      }
    }
  },
  {
    "type": "function",
    "name": "get_issue",
    "description": "Liest ein einzelnes GitHub-Issue (Titel, Body, State, Labels) per Nummer aus dem Snapshot.",
    "parameters": {
      "type": "object",
      "properties": {
        "issueNumber": {
          "type": "integer"
        }
      },
      "required": [
        "issueNumber"
      ]
    }
  },
  {
    "type": "function",
    "name": "search_issues",
    "description": "Sucht Issues per Stichwort-Overlap (Titel/Body/Labels). Vor einem CREATE nutzen, um Duplikate zu finden.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        },
        "state": {
          "type": "string",
          "default": "all"
        },
        "limit": {
          "type": "integer",
          "default": 20
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_labels",
    "description": "Listet alle im Snapshot vorkommenden Labels mit Haeufigkeit.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "get_unmapped_pbis",
    "description": "Die PBIs OHNE bekanntes GitHub-Mapping (nicht blockiert). Fuer jedes: erst search_issues, dann LINK oder CREATE_ISSUE.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "get_pbi",
    "description": "Liest ein PBI (Titel, goal, acceptanceCriteria) inkl. der abgedeckten Requirement-Texte \u2014 Basis fuer Suche und Issue-Body.",
    "parameters": {
      "type": "object",
      "properties": {
        "pbiId": {
          "type": "string"
        }
      },
      "required": [
        "pbiId"
      ]
    }
  },
  {
    "type": "function",
    "name": "check_forward_plan",
    "description": "Prueft deine geplanten Ops deterministisch (Rev-3: CREATE braucht searchedQueries\u002BsearchEvidence; LINK-Ziel muss existieren). Vor dem Speichern nutzen.",
    "parameters": {
      "type": "object",
      "properties": {
        "ops": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "kind": {
                "type": "string"
              },
              "pbiId": {
                "type": "string"
              },
              "targetIssueNumber": {
                "type": [
                  "integer",
                  "null"
                ]
              },
              "title": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "body": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "labels": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "searchedQueries": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "searchEvidence": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "anchor": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "rationale": {
                "type": "string"
              },
              "origin": {
                "type": "string"
              }
            },
            "required": [
              "kind",
              "pbiId",
              "targetIssueNumber",
              "title",
              "body",
              "labels",
              "searchedQueries",
              "searchEvidence",
              "anchor",
              "rationale",
              "origin"
            ]
          }
        }
      },
      "required": [
        "ops"
      ]
    }
  },
  {
    "type": "function",
    "name": "save_forward_plan",
    "description": "Speichert je unmapped PBI GENAU EIN Op: LINK (targetIssueNumber \u002B anchor) ODER CREATE_ISSUE (title\u002Bbody\u002BsearchedQueries\u002BsearchEvidence). Genau einmal.",
    "parameters": {
      "type": "object",
      "properties": {
        "ops": {
          "type": "array",
